#define NX_SECURE_SOURCE_CODE

#include "nx_secure_dtls.h"

/* Shortest secret accepted: 128 bits.  */
#define NX_SECURE_DTLS_COOKIE_SECRET_MINIMUM_SIZE 16u

/**************************************************************************/
/*                                                                        */
/*  FUNCTION                                               RELEASE        */
/*                                                                        */
/*    _nxe_secure_dtls_server_cookie_secret_set           PORTABLE C      */
/*                                                                        */
/*  DESCRIPTION                                                           */
/*                                                                        */
/*    This function checks for errors when setting the secret from which  */
/*    a DTLS server derives its cookie keys. A secret must be 16 to       */
/*    NX_SECURE_DTLS_COOKIE_SECRET_SIZE bytes long; a length of zero      */
/*    returns the server to NX_RAND.                                      */
/*                                                                        */
/*  INPUT                                                                 */
/*                                                                        */
/*    server_ptr                            DTLS server control block     */
/*    secret                                Secret                        */
/*    secret_length                         Length of secret              */
/*                                                                        */
/*  OUTPUT                                                                */
/*                                                                        */
/*    status                                Completion status             */
/*                                                                        */
/*  CALLS                                                                 */
/*                                                                        */
/*    _nx_secure_dtls_server_cookie_secret_set                            */
/*                                          Actual function call          */
/*                                                                        */
/*  CALLED BY                                                             */
/*                                                                        */
/*    Application Code                                                    */
/*                                                                        */
/**************************************************************************/
UINT _nxe_secure_dtls_server_cookie_secret_set(NX_SECURE_DTLS_SERVER *server_ptr,
                                               const UCHAR *secret, UINT secret_length)
{
#ifdef NX_SECURE_ENABLE_DTLS
UINT status;

    if ((server_ptr == NX_NULL) || ((secret == NX_NULL) && (secret_length != 0u)))
    {
        status = NX_PTR_ERROR;
    }
    else if ((secret_length != 0u) &&
             ((secret_length < NX_SECURE_DTLS_COOKIE_SECRET_MINIMUM_SIZE) ||
              (secret_length > NX_SECURE_DTLS_COOKIE_SECRET_SIZE)))
    {
        status = NX_INVALID_PARAMETERS;
    }
    else
    {
        status = _nx_secure_dtls_server_cookie_secret_set(server_ptr, secret, secret_length);
    }

    return(status);
#else
    NX_PARAMETER_NOT_USED(server_ptr);
    NX_PARAMETER_NOT_USED(secret);
    NX_PARAMETER_NOT_USED(secret_length);

    return(NX_NOT_SUPPORTED);
#endif /* NX_SECURE_ENABLE_DTLS */
}
